{
  "references": [
    {"id": "R1", "summary_ko": "사람이 회색 도구를 옆에 내려놓자 손에 다른 도구가 나타남."},
    {"id": "R2", "summary_ko": "도구를 바꾸기 전 첫 동작을 바탕으로 볼 때 사람의 손 움직임이 비정상적임."},
    {"id": "R3", "summary_ko": "남자가 용접 장비 없이 용접하는 것처럼 보이고 뜨거운 금속을 맨손으로 만짐."}
  ],
  "candidates": [
    {"id": "C1", "summary_ko": "테이블 위의 금속 파이프 구조물이 사라지고 고립된 원기둥으로 대체됨."},
    {"id": "C2", "summary_ko": "테이블 표면에 검은색 원통형 도구가 갑자기 나타남."},
    {"id": "C3", "summary_ko": "쥐고 있는 동안 도구 손잡이의 기하학적 형태가 깜빡이고 방향이 불규칙하게 변함."}
  ],
  "pairs": [
    {"reference_id": "R1", "candidate_id": "C1", "verdict": "different", "reason_ko": "도구가 손에 나타나는 현상과 테이블 위 파이프 구조물의 사라짐 및 대체 현상은 대상과 결함이 다릅니다."},
    {"reference_id": "R1", "candidate_id": "C2", "verdict": "uncertain", "reason_ko": "도구가 갑자기 나타나는 현상은 유사하지만, 손에 나타나는 것과 테이블 표면에 나타나는 위치 및 세부 대상이 일치하는지 불확실합니다."},
    {"reference_id": "R1", "candidate_id": "C3", "verdict": "different", "reason_ko": "다른 도구가 손에 갑자기 생성되는 현상과 손잡이 형태가 깜빡거리며 뒤틀리는 현상은 다른 결함입니다."},
    {"reference_id": "R2", "candidate_id": "C1", "verdict": "different", "reason_ko": "사람의 비정상적인 손 움직임과 테이블 위 파이프 구조물의 변형은 서로 다릅니다."},
    {"reference_id": "R2", "candidate_id": "C2", "verdict": "different", "reason_ko": "손 동작의 이상과 테이블 위 도구의 갑작스러운 출현은 다른 현상입니다."},
    {"reference_id": "R2", "candidate_id": "C3", "verdict": "different", "reason_ko": "손 자체의 비정상적 움직임과 쥐고 있는 도구 손잡이의 형태 깜빡임/왜곡은 대상과 현상이 다릅니다."},
    {"reference_id": "R3", "candidate_id": "C1", "verdict": "different", "reason_ko": "용접 장비 미사용 및 뜨거운 금속 접촉 문제와 파이프 구조물의 소멸/대체 결함은 서로 다릅니다."},
    {"reference_id": "R3", "candidate_id": "C2", "verdict": "different", "reason_ko": "용접 및 맨손 접촉 문제와 검은 원통형 도구의 갑작스러운 출현은 관련이 없습니다."},
    {"reference_id": "R3", "candidate_id": "C3", "verdict": "different", "reason_ko": "용접 장비 미사용과 도구 손잡이의 기하학적 깜빡임은 서로 다른 현상입니다."}
  ]
}
